# Let me debug the component merging issue
from collections import deque, defaultdict

grid_color = lambda r, c: int(grid_lines[r].split()[c])
rows, cols = 19, 12

# Find connected components
visited = set()
all_regions = defaultdict(list)

for r in range(rows):
    for c in range(cols):
        if (r, c) in visited:
            continue
        color = grid_color(r, c)
        if color == 9:
            visited.add((r, c))
            continue

        region = []
        queue = deque([(r, c)])
        visited.add((r, c))

        while queue:
            cr, cc = queue.popleft()
            region.append((cr, cc))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in visited and grid_color(nr, nc) == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        all_regions[color].append(sorted(region))
        print(f"Color {color}: {len(region)} cells, topo-left={sorted(region)[0]}")

print("\n--- Number of regions per color ---")
for color in sorted(all_regions.keys()):
    print(f"  {color}: {len(all_regions[color])} region(s)")

# Apply rule: multi-component = keep all, single-component = collapse to topo-left
output5 = [[9 for _ in range(12)] for _ in range(19)]

for color in all_regions:
    regions = all_regions[color]
    if len(regions) > 1:
        # Keep all cells
        for reg in regions:
            for pos in reg:
                output5[pos[0]][pos[1]] = color
    else:
        # Collapse single region to top-left
        reg = regions[0]
        output5[reg[0][0]][reg[0][1]] = color

print("\n5. Test output (corrected):")
for row in output5:
    print(', '.join(str(x) for x in row))

